#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, f;
    char grid[500][501];
    int queue[500 * 500];

    if (scanf("%d %d", &n, &f) != 2) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%500s", grid[i]);
    }

    int head = 0, tail = 0;
    if (grid[0][0] <= '0' + f) {
        grid[0][0] = '*';
        queue[tail++] = 0;
    }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    while (head < tail) {
        int pos = queue[head++];
        int r = pos / n;
        int c = pos % n;

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr >= 0 && nr < n && nc >= 0 && nc < n &&
                grid[nr][nc] != '*' && grid[nr][nc] <= '0' + f) {
                grid[nr][nc] = '*';
                queue[tail++] = nr * n + nc;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        puts(grid[i]);
    }

    return 0;
}
